def resolve(path, cwd, links):
    # Normalize the starting path
    if not path.startswith('/'):
        current = cwd
    else:
        current = '/'

    # Split path into components
    if path.startswith('/'):
        remaining = path[1:]
    else:
        remaining = path

    components = remaining.split('/') if remaining else []

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        comp = components[i]
        i += 1

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            continue

        # Handle '..'
        if comp == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
            continue

        # Append component to current path
        if current == '/':
            candidate = '/' + comp
        else:
            candidate = current + '/' + comp

        # Check if candidate is a symlink
        if candidate in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[candidate]

            # Resolve the target
            if target.startswith('/'):
                current = '/'
                remaining_target = target[1:]
            else:
                # Target is relative to the directory containing the link
                if candidate == '/':
                    current = '/'
                else:
                    current = candidate.rsplit('/', 1)[0]
                    if not current:
                        current = '/'
                remaining_target = target

            # Parse target components and insert them before remaining components
            target_components = remaining_target.split('/') if remaining_target else []
            components = target_components + components[i:]
            i = 0
        else:
            current = candidate

    # Return result without trailing slash (except for '/')
    if current == '/':
        return '/'
    else:
        return current

